project_files.commands.py:
def revise(db, parcel_id, contents):
    db.execute('UPDATE parcels SET revision=revision+1, contents=?, clearance=NULL WHERE id=?', (contents, parcel_id))
    db.commit()

def request_scan(db, scanner, parcel_id):
    row = db.execute('SELECT revision, contents FROM parcels WHERE id=?', (parcel_id,)).fetchone()
    scanner.submit(parcel_id, row[0], row[1])

project_files.schema.sql:
CREATE TABLE parcels(id INTEGER PRIMARY KEY, revision INTEGER NOT NULL, contents TEXT NOT NULL, clearance TEXT);
CREATE TABLE inspection_history(parcel_id INTEGER, revision INTEGER, result TEXT);
CREATE TABLE release_notices(parcel_id INTEGER, revision INTEGER);

project_files.worker.py:
def complete(db, parcel_id, revision, result):
    db.execute('INSERT INTO inspection_history VALUES(?,?,?)', (parcel_id, revision, result))
    db.execute('UPDATE parcels SET clearance=? WHERE id=?', (result, parcel_id))
    if result == 'clear':
        db.execute('INSERT INTO release_notices VALUES(?,?)', (parcel_id, revision))
    db.commit()
